import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { getOne, nowIso, openDatabase, toJob, transaction, type Job, type JobRow } from './db.ts';

const MAX_BODY_BYTES = 1024 * 1024;
const HEARTBEAT_FRESH_MS = 3000;
const ALLOWED_FIELDS = ['input', 'steps', 'failAttempts'];
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const SHUTDOWN_GRACE_MS = 3000;

interface FieldError {
  field: string;
  message: string;
}

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const stmtJobByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const stmtInsertJob = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed,
     idempotency_key, payload, run_after, created_at, updated_at)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
);
const stmtJobById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const stmtListJobs = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const stmtHeartbeat = db.prepare('SELECT beat_at FROM heartbeat WHERE id = 1');

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[], headers?: Record<string, string>): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error }, headers);
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function isIntInRange(v: unknown, min: number, max: number): v is number {
  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
}

function readBody(req: IncomingMessage): Promise<{ buf: Buffer; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ buf: Buffer.concat(chunks), tooLarge }));
    req.on('error', reject);
  });
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { buf, tooLarge } = await readBody(req);
  const errors: FieldError[] = [];

  const mediaType = String(req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    errors.push({ field: 'body', message: 'Content-Type must be application/json.' });
    errors.push({ field: 'Content-Type', message: 'Content-Type must be application/json.' });
  }

  const key = req.headers['idempotency-key'];
  if (key !== undefined && !IDEMPOTENCY_KEY_RE.test(key)) {
    errors.push({ field: 'Idempotency-Key', message: 'Must be 1-128 characters of letters, digits, "_" or "-".' });
  }

  let parsed: unknown;
  let parsedOk = false;
  if (tooLarge) {
    errors.push({ field: 'body', message: `Request body must be at most ${MAX_BODY_BYTES} bytes.` });
  } else {
