import { setTimeout as sleep } from 'node:timers/promises';
import { getOne, nowIso, openDatabase, transaction, type JobRow } from './db.ts';

const STEP_MS = 100;
const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 500;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;
const FORCED_EXIT_MS = 4000;

const db = openDatabase();
let stopping = false;

const stmtBeat = db.prepare(
  'INSERT INTO heartbeat (id, beat_at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET beat_at = excluded.beat_at',
);
const stmtPickNext = db.prepare(
  "SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1",
);
const stmtMarkRunning = db.prepare(
  "UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE id = ? AND status = 'queued'",
);
const stmtSetProgress = db.prepare(
  "UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'",
);
const stmtComplete = db.prepare(
  "UPDATE jobs SET status = 'completed', result_output = ?, progress_completed = steps, updated_at = ? WHERE id = ? AND status = 'running'",
);
const stmtFail = db.prepare(
  "UPDATE jobs SET status = 'failed', error = 'transient failure', result_output = NULL, progress_completed = 0, updated_at = ? WHERE id = ? AND status = 'running'",
);
const stmtRetryLater = db.prepare(
  "UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'",
);
const stmtRequeue = db.prepare(
  "UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0, run_after = 0, updated_at = ? WHERE id = ? AND status = 'running'",
);

/** Returns jobs interrupted by a previous worker to the queue. Their interrupted attempt is re-run with the same number. */
function recoverInterrupted(): void {
  db.prepare(
    "UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'",
  ).run(nowIso());
}

/** Atomically claims the oldest runnable job and marks it running for a new attempt. */
function claimNext(): JobRow | undefined {
  return transaction(db, () => {
    const row = getOne<JobRow>(stmtPickNext, Date.now());
    if (!row) return undefined;
    stmtMarkRunning.run(nowIso(), row.id);
    return { ...row, status: 'running', attempts: row.attempts + 1, progress_completed: 0 };
  });
}

function requeue(job: JobRow): void {
  stmtRequeue.run(nowIso(), job.id);
}

/** Processes one attempt of a claimed job. `job.attempts` already includes this attempt. */
async function processAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  await sleep(STEP_MS);
  if (stopping) return requeue(job);

  if (attempt <= job.fail_attempts) {
    if (attempt < MAX_ATTEMPTS) {
      stmtRetryLater.run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
    } else {
      stmtFail.run(nowIso(), job.id);
    }
    return;
  }

  for (let i = 1; i <= job.steps; i++) {
    await sleep(STEP_MS);
    if (stopping) return requeue(job);
    stmtSetProgress.run(i, nowIso(), job.id);
  }

  stmtComplete.run(job.input.toUpperCase(), nowIso(), job.id);
}

function startHeartbeat(): NodeJS.Timeout {
  const beat = () => {
    try {
      stmtBeat.run(Date.now());
    } catch (e) {
      console.error('heartbeat failed:', e);
    }
  };
  beat();
  return setInterval(beat, HEARTBEAT_MS);
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
    setTimeout(() => process.exit(0), FORCED_EXIT_MS).unref();
  });
}

recoverInterrupted();
const heartbeat = startHeartbeat();
console.log('worker started');

while (!stopping) {
  try {
    const job = claimNext();
    if (job) await processAttempt(job);
    else await sleep(IDLE_POLL_MS);
  } catch (e) {
    console.error('worker error:', e);
    await sleep(IDLE_POLL_MS);
  }
}

clearInterval(heartbeat);
try {
  db.prepare('UPDATE heartbeat SET beat_at = 0 WHERE id = 1').run();
} catch {
  // best effort: the heartbeat goes stale anyway
}
db.close();
console.log('worker stopped');
process.exit(0);

