import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { getOne, nowIso, openDatabase, toJob, transaction, type Job, type JobRow } from './db.ts';

const MAX_BODY_BYTES = 1024 * 1024;
const HEARTBEAT_FRESH_MS = 3000;
const ALLOWED_FIELDS = ['input', 'steps', 'failAttempts'];
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const SHUTDOWN_GRACE_MS = 3000;

interface FieldError {
  field: string;
  message: string;
}

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const stmtJobByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const stmtInsertJob = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed,
     idempotency_key, payload, run_after, created_at, updated_at)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
);
const stmtJobById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const stmtListJobs = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const stmtHeartbeat = db.prepare('SELECT beat_at FROM heartbeat WHERE id = 1');

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[], headers?: Record<string, string>): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error }, headers);
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function isIntInRange(v: unknown, min: number, max: number): v is number {
  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
}

function readBody(req: IncomingMessage): Promise<{ buf: Buffer; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ buf: Buffer.concat(chunks), tooLarge }));
    req.on('error', reject);
  });
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { buf, tooLarge } = await readBody(req);
  const errors: FieldError[] = [];

  const mediaType = String(req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    errors.push({ field: 'body', message: 'Content-Type must be application/json.' });
    errors.push({ field: 'Content-Type', message: 'Content-Type must be application/json.' });
  }

  const key = req.headers['idempotency-key'];
  if (key !== undefined && !IDEMPOTENCY_KEY_RE.test(key)) {
    errors.push({ field: 'Idempotency-Key', message: 'Must be 1-128 characters of letters, digits, "_" or "-".' });
  }

  let parsed: unknown;
  let parsedOk = false;
  if (tooLarge) {
    errors.push({ field: 'body', message: `Request body must be at most ${MAX_BODY_BYTES} bytes.` });
  } else {
    try {
      parsed = JSON.parse(buf.toString('utf8'));
      parsedOk = true;
    } catch {
      errors.push({ field: 'body', message: 'Request body must be valid JSON.' });
    }
  }

  if (parsedOk && !isPlainObject(parsed)) {
    errors.push({ field: 'body', message: 'Request body must be a JSON object.' });
  }

  let input = '';
  let steps = 5;
  let failAttempts = 0;
  if (parsedOk && isPlainObject(parsed)) {
    for (const name of Object.keys(parsed)) {
      if (!ALLOWED_FIELDS.includes(name)) errors.push({ field: name, message: 'Unknown field.' });
    }

    const rawInput = parsed.input;
    if (typeof rawInput !== 'string' || rawInput.length < 1 || rawInput.length > 1000 || rawInput.trim() === '') {
      errors.push({ field: 'input', message: 'Must be a string of 1 to 1000 characters that is not only whitespace.' });
    } else {
      input = rawInput;
    }

    if (parsed.steps !== undefined) {
      if (isIntInRange(parsed.steps, 1, 20)) steps = parsed.steps;
      else errors.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
    }

    if (parsed.failAttempts !== undefined) {
      if (isIntInRange(parsed.failAttempts, 0, 5)) failAttempts = parsed.failAttempts;
      else errors.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
    }
  }

  if (errors.length > 0) {
    sendError(res, 400, 'invalid_request', 'The job submission is invalid.', errors);
    return;
  }

  const payload = JSON.stringify({ input, steps, failAttempts });
  const idempotencyKey = key;

  type Outcome = { kind: 'created' | 'replayed'; job: Job } | { kind: 'conflict' };
  const outcome: Outcome = transaction(db, (): Outcome => {
    if (idempotencyKey !== undefined) {
      const existing = getOne<JobRow>(stmtJobByKey, idempotencyKey);
      if (existing) {
        if (existing.payload === payload) return { kind: 'replayed', job: toJob(existing) };
        return { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    const now = nowIso();
    stmtInsertJob.run(id, input, steps, failAttempts, idempotencyKey ?? null, payload, now, now);
    const created = getOne<JobRow>(stmtJobById, id)!;
    return { kind: 'created', job: toJob(created) };
  });

  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used for a different job submission.');
  } else if (outcome.kind === 'replayed') {
    send(res, 200, outcome.job);
  } else {
    send(res, 201, outcome.job);
  }
}

function listJobs(_req: IncomingMessage, res: ServerResponse): void {
  const rows = stmtListJobs.all() as unknown as JobRow[];
  send(res, 200, { jobs: rows.map(toJob) });
}

function getJob(id: string, res: ServerResponse): void {
  const row = getOne<JobRow>(stmtJobById, id);
  if (!row) {
    sendError(res, 404, 'not_found', 'No job with that id.');
    return;
  }
  send(res, 200, toJob(row));
}

function health(_req: IncomingMessage, res: ServerResponse): void {
  const beat = getOne<{ beat_at: number }>(stmtHeartbeat);
  const up = beat !== undefined && Date.now() - Number(beat.beat_at) < HEARTBEAT_FRESH_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function page(_req: IncomingMessage, res: ServerResponse): void {
  res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
  res.end(uiHtml);
}

type Handler = (req: IncomingMessage, res: ServerResponse) => void | Promise<void>;

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? '';

  let methods: string[] | undefined;
  let handler: Handler | undefined;
  if (pathname === '/health') {
    methods = ['GET'];
    handler = health;
  } else if (pathname === '/') {
    methods = ['GET'];
    handler = page;
  } else if (pathname === '/api/jobs') {
    methods = ['GET', 'POST'];
    handler = method === 'POST' ? createJob : listJobs;
  } else {
    const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
    if (match) {
      const id = match[1]!;
      methods = ['GET'];
      handler = (_req, r) => getJob(id, r);
    }
  }

  if (!methods || !handler) {
    sendError(res, 404, 'not_found', 'No such route.');
    return;
  }
  if (!methods.includes(method)) {
    sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here.`, undefined, { allow: methods.join(', ') });
    return;
  }
  await handler(req, res);
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (res.headersSent) res.end();
    else sendError(res, 500, 'internal_error', 'Unexpected server error.');
  });
});

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  setTimeout(() => process.exit(0), SHUTDOWN_GRACE_MS).unref();
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

server.listen(port, () => console.log(`server listening on ${port}`));

